// Published reports are generated by Actions. Reading/downloading never calls an LLM.
(function (root, factory) {
  const api = factory(root);
  if (typeof module === 'object' && module.exports) module.exports = api;
  if (root) root.DPRDeepReading = api;
})(typeof window !== 'undefined' ? window : null, function (root) {
  const BEGIN = '<!-- DPR-DEEP-REPORT:BEGIN -->';
  const END = '<!-- DPR-DEEP-REPORT:END -->';
  let currentRoute = '';
  let mountVersion = 0;

  const extractReport = (source) => {
    const text = String(source || '');
    const a = text.indexOf(BEGIN);
    const b = text.indexOf(END, a);
    if (a >= 0 && b > a) return text.slice(a + BEGIN.length, b).replace(/^\s*## 论文详细总结（自动生成）\s*/, '').trim();
    const match = /^## 论文详细总结（自动生成）\s*\n([\s\S]*)/m.exec(text);
    if (!match) return '';
    return match[1].split(/^## (?:我的笔记|笔记|Notes|讨论)\s*$/m)[0].trim();
  };

  const absoluteImages = (markdown, sourceUrl) => String(markdown || '').replace(
    /(!\[[^\]]*\]\()([^\s)]+)([^)]*\))/g,
    (whole, before, url, after) => {
      if (/^(?:https?:|data:)/i.test(url)) return whole;
      try { return before + new URL(url, sourceUrl).href + after; } catch { return whole; }
    },
  );

  const parseRoutes = (value) => {
    const routes = [...new Set(String(value || '').split(/[\n,]+/).map(x => x.trim().replace(/^docs\//, '').replace(/\.md$/i, '')).filter(Boolean))];
    if (!routes.length || routes.length > 20) throw new Error('请选择 1–20 篇精读论文。');
    if (routes.some(x => !/^[A-Za-z0-9_-]+(?:\/[A-Za-z0-9_.-]+)+$/.test(x) || x.split('/').some(y => y === '.' || y === '..'))) throw new Error('请输入站内论文 route，例如 202610/19/论文标识。');
    return routes;
  };

  const download = (text, route) => {
    const blob = new Blob([absoluteImages(text, new URL('docs/' + route, root.location.href).href)], { type: 'text/markdown;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = route.split('/').pop().replace(/\.md$/i, '') + '-研究报告.md';
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  const showBackfillDialog = (route = currentRoute) => {
    document.getElementById('dpr-report-dialog')?.remove();
    const dialog = document.createElement('dialog');
    dialog.id = 'dpr-report-dialog';
    dialog.className = 'dpr-report-dialog';
    dialog.innerHTML = `<form method="dialog">
      <h2>补生成精读报告</h2>
      <p>仅为下列已有精读论文生成十二节报告，不重新检索或评分。报告会发布到本站；使用 GitHub 工作流中的模型配置，按实际调用计费，成功缓存会复用。</p>
      <label for="dpr-report-routes">论文 route（每行一篇，最多 20 篇）</label>
      <textarea id="dpr-report-routes" rows="5" spellcheck="false"></textarea>
      <p data-role="report-count" aria-live="polite"></p>
      <div class="dpr-dialog-actions"><button value="cancel">取消</button><button type="button" data-role="start">生成所选报告</button></div>
    </form>`;
    document.body.appendChild(dialog);
    const input = dialog.querySelector('textarea');
    const status = dialog.querySelector('[data-role="report-count"]');
    const start = dialog.querySelector('[data-role="start"]');
    input.value = route.replace(/\.md$/i, '');
    const update = () => {
      try { status.textContent = `已选 ${parseRoutes(input.value).length} 篇；模型费用与论文长度、所选平台有关。`; start.disabled = false; }
      catch (error) { status.textContent = error.message; start.disabled = true; }
    };
    input.addEventListener('input', update);
    update();
    start.addEventListener('click', async () => {
      const runner = root.DPRWorkflowRunner;
      if (!runner) { status.textContent = '工作流面板尚未加载，请稍后重试。'; return; }
      const routes = parseRoutes(input.value);
      start.disabled = true;
      const ok = await runner.runWorkflowByKey('deep-reading-report', { routes: routes.join('\n') });
      if (ok) dialog.close();
      else { status.textContent = '未确认提交成功，请查看工作流面板提示。'; start.disabled = false; }
    });
    dialog.addEventListener('click', event => { if (event.target === dialog) dialog.close(); });
    dialog.addEventListener('close', () => dialog.remove());
    dialog.showModal();
  };

  const mountForPage = async ({ routeFile, meta } = {}) => {
    const version = ++mountVersion;
    currentRoute = routeFile || '';
    const bar = document.querySelector('.dpr-paper-action-bar');
    if (!bar || !currentRoute || String((meta || {}).reading_section) !== 'deep') return;
    const route = currentRoute;
    const button = document.createElement('button');
    button.className = 'dpr-paper-action-btn';
    button.textContent = '下载研究报告 .md';
    button.disabled = true;
    bar.querySelector('[data-role="report-download"]')?.remove();
    button.dataset.role = 'report-download';
    bar.querySelector('[data-action="download-md"]')?.insertAdjacentElement('afterend', button);
    try {
      let response = await fetch('docs/' + route.replace(/\.md$/i, '.report.md'), { cache: 'no-cache' });
      let report;
      if (response.ok) report = await response.text();
      else if (response.status === 404) {
        response = await fetch('docs/' + route, { cache: 'no-cache' });
        if (!response.ok) throw new Error('读取报告失败');
        report = extractReport(await response.text());
      } else throw new Error('读取报告失败');
      if (version !== mountVersion || !button.isConnected) return;
      if (report) {
        button.disabled = false;
        button.addEventListener('click', () => download(report, route));
      } else button.title = '尚未发布报告，可选择补生成。';
    } catch { button.title = '报告暂时无法读取，请刷新后重试。'; }
  };

  return { extractReport, absoluteImages, parseRoutes, mountForPage, showBackfillDialog,
    generateForPage: () => showBackfillDialog(), isDeepPaper: () => !!currentRoute };
});
